def main():
    for i, code in enumerate(LANGS):
        strings = {k: v[i] for k, v in sorted(R.items())}
        data = {"_comment": "Translations of the German table puzzle_spots, written by tools/i18n/locales_puzzle_spots.py. "
                "Keys are the English text; keys with %s or %d are patterns.", "strings": strings}
        path = os.path.join(ROOT, "data/i18n", code, "puzzle_spots.json")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(json.dumps(data, ensure_ascii=False, indent=1) + "\n")
    print("puzzle_spots: %d strings x %d locales" % (len(R), len(LANGS)))


if __name__ == "__main__":
    main()
